WITH parsed AS (SELECT id, tier_prices, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, SLICE(tier_limits, 1, 2) AS first_two_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT CASE WHEN entry_price >= 27 THEN 'HIGH' ELSE 'LOW' END AS entry_price_tier, AVG(entry_price) AS avg_entry_price, APPROX_PERCENTILE(entry_price, ARRAY(0.25, 0.5, 0.75)) AS entry_price_quartiles, COUNT(*) AS cnt FROM parsed GROUP BY 1 ORDER BY avg_entry_price NULLS FIRST
